insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-nap-gai-carton-27x18x7cm', 'Hộp nắp gài Carton 27x18x7cm', null, 'hop-nap-gai', 480000, 2400000, '[{"qty":100,"price":480000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":2400000}]'::jsonb, 'Carton 3 lớp sóng E (2N+X), kích thước 27 x 18 x 7 cm, màu trắng hoặc nâu. Nắp gập kiểu thời trang, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp nắp gài Carton 27x18x7cm là hộp nắp gài do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng e (2n+x), sóng cao 2mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gập kiểu thời trang. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng E (2N+X)","Kích thước (D x R x C)":"27 x 18 x 7 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"2mm","Kiểu hộp":"Nắp gập kiểu thời trang","Kỹ thuật in":"Không in sẵn — nhận in theo yêu cầu từ 500 hộp","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img11.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], false)
  on conflict (slug) do update set name = excluded.name, sku = excluded.sku, category_slug = excluded.category_slug, price_min = excluded.price_min, price_max = excluded.price_max, price_tiers = excluded.price_tiers, short_description = excluded.short_description, description = excluded.description, specs = excluded.specs, images = excluded.images, is_featured = excluded.is_featured;
insert into public.products (slug, name, sku, category_slug, price_min, price_max, price_tiers, short_description, description, specs, images, is_featured) values ('hop-carton-15x10x20cm', 'Hộp Carton 15x10x20cm', 'LTCOD-007', 'thung-cod', 350000, 1719000, '[{"qty":100,"price":350000},{"qty":200,"price":null},{"qty":300,"price":null},{"qty":400,"price":null},{"qty":500,"price":1719000}]'::jsonb, 'Carton 3 lớp sóng B (2 mặt nâu, 1 lớp sóng), kích thước 15 x 10 x 20 cm, màu trắng hoặc nâu. Nắp gài kiểu tiết kiệm, gấp gọn được để tiết kiệm chi phí lưu kho và vận chuyển.', '<p>Hộp Carton 15x10x20cm là thùng carton COD do Công Ty TNHH Công Nghiệp Thời Đại sản xuất trực tiếp tại xưởng, không qua trung gian. Thùng dùng carton 3 lớp sóng b (2 mặt nâu, 1 lớp sóng), sóng cao 3mm — vừa giữ được độ phẳng và tính thẩm mỹ của bề mặt giấy, vừa chống va đập tốt khi vận chuyển.</p><p>Kiểu hộp: nắp gài kiểu tiết kiệm. Hộp giao ở dạng phôi phẳng, khách tự gấp khi đóng hàng, nhờ đó giảm đáng kể chi phí lưu kho và cước vận chuyển.</p><p>Nhận in logo, nhận diện thương hiệu theo yêu cầu với đơn từ 500 hộp. Đơn trên 500 hộp liên hệ Zalo 0399 466 179 (Ms. Tuyền) để nhận giá ưu đãi. Xưởng nhận sản xuất carton 3 lớp, 5 lớp, 7 lớp với các loại sóng B, C, E theo kích thước riêng của khách.</p>', '{"Chất liệu":"Carton 3 lớp sóng B (2 mặt nâu, 1 lớp sóng)","Kích thước (D x R x C)":"15 x 10 x 20 cm","Màu sắc":"Trắng, nâu","Chiều cao sóng":"3mm","Kiểu hộp":"Nắp gài kiểu tiết kiệm","Kỹ thuật in":"In Flexo 1 màu","Số lượng đặt tối thiểu":"100 hộp","Nhận in theo yêu cầu":"Từ 500 hộp"}'::jsonb, ARRAY['/assets/images/thumbs/shop-img12.png', '/assets/images/thumbs/shop-details-thumb1.png', '/assets/images/thumbs/shop-details-thumb2.png', '/assets/images/thumbs/shop-details-thumb3.png']::text[], true)
